"use strict";(self.webpackChunkucl_artificial_intelligence_society=self.webpackChunkucl_artificial_intelligence_society||[]).push([[5961],{9691:e=>{e.exports=JSON.parse('{"collection":"nexus","route":"/learn/nexus/2026-27/launch.md/","sourcePath":"knowledge/nexus/2026-27/launch.md","fileUrl":"https://github.com/UCLAIS/UCLAIS.github.io/blob/24e06da03aa538cbc002767935da6d95d724ede8/knowledge/nexus/2026-27/launch.md","format":"md","document":{"id":"knowledge:nexus/2026-27/launch.md","title":"Nexus Labs 2026/27 launch","sections":[{"id":"section-1","heading":"What we covered","text":"Notes from all 14 pages of the supplied Nexus Labs 2026/27 launch presentation: the team, four research pillars, research framework, tracks, conference-planning timeline and application routes. The deck does not give a launch date or numbered session, so neither is assigned here.\\n\\n[Download the archived launch slides (PDF)](https://uclai.co.uk/materials/nexus/2026-27/nexus-labs-launch.pdf). The download preserves the 14 slide pages, with document metadata removed.\\n\\nThis is a record of the launch presentation. Its application QR codes, roles and planning dates must not be treated as evidence of current availability or deadlines. For current programme information, use the [Nexus Labs page](https://uclai.co.uk/our-initiatives/Nexus-Labs/); upcoming society events come from the [society\'s Luma calendar](https://luma.com/UCLAISociety).","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"Notes from all 14 pages of the supplied Nexus Labs 2026/27 launch presentation: the team, four research pillars, research framework, tracks, conference-planning timeline and application routes. The deck does not give a launch date or numbered session, so neither is assigned here."}]},{"type":"paragraph","children":[{"type":"link","href":"https://uclai.co.uk/materials/nexus/2026-27/nexus-labs-launch.pdf","children":[{"type":"text","value":"Download the archived launch slides (PDF)"}]},{"type":"text","value":". The download preserves the 14 slide pages, with document metadata removed."}]},{"type":"paragraph","children":[{"type":"text","value":"This is a record of the launch presentation. Its application QR codes, roles and planning dates must not be treated as evidence of current availability or deadlines. For current programme information, use the "},{"type":"link","href":"https://uclai.co.uk/our-initiatives/Nexus-Labs/","children":[{"type":"text","value":"Nexus Labs page"}]},{"type":"text","value":"; upcoming society events come from the "},{"type":"link","href":"https://luma.com/UCLAISociety","children":[{"type":"text","value":"society\'s Luma calendar"}]},{"type":"text","value":"."}]}]},{"id":"section-2","heading":"Launch context (pages 1\u20132)","text":"The presentation introduces Nexus Labs as UCL AI Society\'s 2026/27 research programme. The cover includes promotional size/ranking claims; these have not been independently verified for these notes and should not be used as established current rankings. Page 2 is a Nexus Labs title slide.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"The presentation introduces Nexus Labs as UCL AI Society\'s 2026/27 research programme. The cover includes promotional size/ranking claims; these have not been independently verified for these notes and should not be used as established current rankings. Page 2 is a Nexus Labs title slide."}]}]},{"id":"section-3","heading":"People introduced at the launch (page 3)","text":"- **Aryan Rishi:** introduced as a co-head of Nexus Labs and a third-year MEng Robotics and Artificial Intelligence student.\\n- **Edwin Redhead:** introduced as a co-head of Nexus Labs and a third-year MEng Robotics and Artificial Intelligence student.\\n- **Aiden (Yiliu) Li:** introduced as the former head of Nexus Labs and a BSc Computer Science graduate.\\n\\nThese are the roles and biographies stated on the launch slide, rather than a continuously updated contact directory.","kind":"explanation","nodes":[{"type":"list","ordered":false,"children":[{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Aryan Rishi:"}]},{"type":"text","value":" introduced as a co-head of Nexus Labs and a third-year MEng Robotics and Artificial Intelligence student."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Edwin Redhead:"}]},{"type":"text","value":" introduced as a co-head of Nexus Labs and a third-year MEng Robotics and Artificial Intelligence student."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Aiden (Yiliu) Li:"}]},{"type":"text","value":" introduced as the former head of Nexus Labs and a BSc Computer Science graduate."}]}]}]},{"type":"paragraph","children":[{"type":"text","value":"These are the roles and biographies stated on the launch slide, rather than a continuously updated contact directory."}]}]},{"id":"section-4","heading":"How does it work? (page 4)","text":"Page 4 is a section divider. The programme structure is explained by the following pillar, framework and track slides; it does not supply additional operational rules on this page.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"Page 4 is a section divider. The programme structure is explained by the following pillar, framework and track slides; it does not supply additional operational rules on this page."}]}]},{"id":"section-5","heading":"Four research pillars (page 5)","text":"1. Computational Foundations.\\n2. Embodied Intelligence.\\n3. Human-centred Artificial Intelligence.\\n4. Artificial Intelligence for Biomedicine, described as **AI for Healthcare** on page 6.","kind":"explanation","nodes":[{"type":"list","ordered":true,"children":[{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Computational Foundations."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Embodied Intelligence."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Human-centred Artificial Intelligence."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Artificial Intelligence for Biomedicine, described as "},{"type":"strong","children":[{"type":"text","value":"AI for Healthcare"}]},{"type":"text","value":" on page 6."}]}]}]}]},{"id":"section-6","heading":"AI for Healthcare (page 6)","text":"Apply AI to understanding biological systems, supporting clinical decision-making and accelerating medical discovery. The launch lists:\\n\\n- Medical imaging and diagnostics.\\n- Molecular biology, genomics and drug discovery.\\n- Public health, personalised and preventive medicine.\\n- Clinical decision support and healthcare delivery.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"Apply AI to understanding biological systems, supporting clinical decision-making and accelerating medical discovery. The launch lists:"}]},{"type":"list","ordered":false,"children":[{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Medical imaging and diagnostics."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Molecular biology, genomics and drug discovery."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Public health, personalised and preventive medicine."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Clinical decision support and healthcare delivery."}]}]}]}]},{"id":"section-7","heading":"Computational Foundations (page 7)","text":"Advance the theoretical and algorithmic foundations of AI, including optimisation, learning theory and scalable architectures. Areas listed are:\\n\\n- Machine learning and statistical methods.\\n- Optimisation and numerical computation.\\n- Logic, reasoning and knowledge representation.\\n- Probabilistic and decision-theoretic foundations.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"Advance the theoretical and algorithmic foundations of AI, including optimisation, learning theory and scalable architectures. Areas listed are:"}]},{"type":"list","ordered":false,"children":[{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Machine learning and statistical methods."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Optimisation and numerical computation."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Logic, reasoning and knowledge representation."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Probabilistic and decision-theoretic foundations."}]}]}]}]},{"id":"section-8","heading":"Human-centred Artificial Intelligence (page 8)","text":"Develop AI that collaborates with and remains accountable to people, serves human needs, reflects values and stays understandable. Areas listed are:\\n\\n- Visual computing and multimodal perception.\\n- Human\u2013AI collaboration and interaction.\\n- Explainability, safety and transparency of AI.\\n- Evaluation and human-in-the-loop learning.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"Develop AI that collaborates with and remains accountable to people, serves human needs, reflects values and stays understandable. Areas listed are:"}]},{"type":"list","ordered":false,"children":[{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Visual computing and multimodal perception."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Human\u2013AI collaboration and interaction."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Explainability, safety and transparency of AI."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Evaluation and human-in-the-loop learning."}]}]}]}]},{"id":"section-9","heading":"Embodied Intelligence (page 9)","text":"Study intelligence through physical interaction with an environment, bringing together robotics, perception and control. Areas listed are:\\n\\n- Robot learning and control.\\n- Vision-language-action models.\\n- Sim-to-real transfer and embodied cognition.\\n- Multi-agent and human\u2013robot interaction.\\n\\nPages 6\u20139 also illustrate these themes with healthcare, neural-network, human\u2013robot interaction and robotics images.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"Study intelligence through physical interaction with an environment, bringing together robotics, perception and control. Areas listed are:"}]},{"type":"list","ordered":false,"children":[{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Robot learning and control."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Vision-language-action models."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Sim-to-real transfer and embodied cognition."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Multi-agent and human\u2013robot interaction."}]}]}]},{"type":"paragraph","children":[{"type":"text","value":"Pages 6\u20139 also illustrate these themes with healthcare, neural-network, human\u2013robot interaction and robotics images."}]}]},{"id":"section-10","heading":"Research framework for 2026/27 (page 10)","text":"The launch describes the following aims:\\n\\n- Group applicants with similar research interests.\\n- Facilitate team formation and exchange.\\n- Use peer evaluation during demos and poster sessions.\\n- Connect participants with researchers.\\n- Provide a visible platform for end-of-project presentations.\\n- Support high-quality projects working towards conference submissions.\\n\\nThe slide describes these as programme aims. It does not promise conference acceptance, funding, a particular mentor or a publication.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"The launch describes the following aims:"}]},{"type":"list","ordered":false,"children":[{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Group applicants with similar research interests."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Facilitate team formation and exchange."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Use peer evaluation during demos and poster sessions."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Connect participants with researchers."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Provide a visible platform for end-of-project presentations."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Support high-quality projects working towards conference submissions."}]}]}]},{"type":"paragraph","children":[{"type":"text","value":"The slide describes these as programme aims. It does not promise conference acceptance, funding, a particular mentor or a publication."}]}]},{"id":"section-11","heading":"Advanced and Exploratory tracks (page 11)","text":"**Advanced:** for motivated student researchers with solid technical foundations who can commit consistent time and effort to ambitious projects. The slide describes closer mentorship, professional support and additional resources, with opportunities to work with academic and industry partners. Selection and continuation depend on performance and engagement. Members who struggle with the expected pace may move to the Exploratory track.\\n\\n**Exploratory:** a flexible environment for discovering research, building skills and developing ideas. The launch explicitly presents this as a valuable, supportive route for learning and growth.\\n\\n**Both tracks:** access to events and opportunities to showcase work to society partners and fellow students.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Advanced:"}]},{"type":"text","value":" for motivated student researchers with solid technical foundations who can commit consistent time and effort to ambitious projects. The slide describes closer mentorship, professional support and additional resources, with opportunities to work with academic and industry partners. Selection and continuation depend on performance and engagement. Members who struggle with the expected pace may move to the Exploratory track."}]},{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Exploratory:"}]},{"type":"text","value":" a flexible environment for discovering research, building skills and developing ideas. The launch explicitly presents this as a valuable, supportive route for learning and growth."}]},{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Both tracks:"}]},{"type":"text","value":" access to events and opportunities to showcase work to society partners and fellow students."}]}]},{"id":"section-12","heading":"Conference-planning timeline (page 12; archival)","text":"The image-only timeline gives planning windows by pillar. The dates below are transcribed from that slide, not checked current calls for papers. A tilde (`~`) means the slide presents an approximate date based on recent conference cycles.\\n\\n**Computational Foundations:** IJCAI (~17 January), ICML (~22 January), COLT (~6 February), UAI (~20 February), ICCV (~5 March), NeurIPS (~15 May), AAAI (~1 August), ICLR (25 September), AISTATS (~8 October) and CVPR (16 November).\\n\\n**Human-centred AI:** FAccT (~15 January), SIGGRAPH (~22 January), ACL / ARR February (~15 February), UIST (~1 April), EMNLP / ARR May (~19 May), AIES (~21 May), CHI (~11 September), HRI (~30 September) and NAACL / ARR October (~6 October).\\n\\n**AI for Healthcare:** CHIL (~5 February), MICCAI (~3 March), AMIA (~15 March), MLHC (~15 April), ML4H (~1 September), ISBI (~10 October) and MIDL (~10 December).\\n\\n**Embodied Intelligence:** RSS (~31 January), IROS (~1 March), CASE (~12 March), ALIFE (~20 March), CoRL (~28 May), Humanoids (~15 July), 3DV (~26 August), ICRA (~15 September), AAMAS (~10 October) and L4DC (~8 November).\\n\\nThe slide\'s footnote labels the ICLR and CVPR entries as confirmed 2027 dates, says deadlines are mostly Anywhere on Earth (AoE), and warns that abstracts are often due about a week earlier. Those are statements from the supplied slide, not independent verification. Check the relevant official call for papers before relying on any date, time zone, submission stage or venue-year mapping. These planning entries are not upcoming society events and are not added to the live events feed.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"The image-only timeline gives planning windows by pillar. The dates below are transcribed from that slide, not checked current calls for papers. A tilde ("},{"type":"inlineCode","value":"~"},{"type":"text","value":") means the slide presents an approximate date based on recent conference cycles."}]},{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Computational Foundations:"}]},{"type":"text","value":" IJCAI (~17 January), ICML (~22 January), COLT (~6 February), UAI (~20 February), ICCV (~5 March), NeurIPS (~15 May), AAAI (~1 August), ICLR (25 September), AISTATS (~8 October) and CVPR (16 November)."}]},{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Human-centred AI:"}]},{"type":"text","value":" FAccT (~15 January), SIGGRAPH (~22 January), ACL / ARR February (~15 February), UIST (~1 April), EMNLP / ARR May (~19 May), AIES (~21 May), CHI (~11 September), HRI (~30 September) and NAACL / ARR October (~6 October)."}]},{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"AI for Healthcare:"}]},{"type":"text","value":" CHIL (~5 February), MICCAI (~3 March), AMIA (~15 March), MLHC (~15 April), ML4H (~1 September), ISBI (~10 October) and MIDL (~10 December)."}]},{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Embodied Intelligence:"}]},{"type":"text","value":" RSS (~31 January), IROS (~1 March), CASE (~12 March), ALIFE (~20 March), CoRL (~28 May), Humanoids (~15 July), 3DV (~26 August), ICRA (~15 September), AAMAS (~10 October) and L4DC (~8 November)."}]},{"type":"paragraph","children":[{"type":"text","value":"The slide\'s footnote labels the ICLR and CVPR entries as confirmed 2027 dates, says deadlines are mostly Anywhere on Earth (AoE), and warns that abstracts are often due about a week earlier. Those are statements from the supplied slide, not independent verification. Check the relevant official call for papers before relying on any date, time zone, submission stage or venue-year mapping. These planning entries are not upcoming society events and are not added to the live events feed."}]}]},{"id":"section-13","heading":"Application routes shown at the launch (page 13)","text":"The slide has three QR codes labelled:\\n\\n- Nexus Labs student researcher applications 2026/2027.\\n- Nexus Labs pillar officer application form 2026/27.\\n- UCL AI Nexus Labs 2026/27 academic mentor registration.\\n\\nThe labels were read visually; the QR destinations have not been decoded or followed. The archived PDF retains the codes. Their presence does not establish that applications or registrations are open now. Use the current Nexus Labs page for availability and links.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"The slide has three QR codes labelled:"}]},{"type":"list","ordered":false,"children":[{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Nexus Labs student researcher applications 2026/2027."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"Nexus Labs pillar officer application form 2026/27."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"text","value":"UCL AI Nexus Labs 2026/27 academic mentor registration."}]}]}]},{"type":"paragraph","children":[{"type":"text","value":"The labels were read visually; the QR destinations have not been decoded or followed. The archived PDF retains the codes. Their presence does not establish that applications or registrations are open now. Use the current Nexus Labs page for availability and links."}]}]},{"id":"section-14","heading":"Closing slide (page 14)","text":"The presentation closes with \u201cSee you next time!\u201d No additional requirements, exercises, hints or solutions are supplied.\\n\\nFor questions the launch slides do not answer, uncertain policies or corrections, email [info@uclai.co.uk](mailto:info@uclai.co.uk). AI answers may be incorrect; check the cited source pages and current dates.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"The presentation closes with \u201cSee you next time!\u201d No additional requirements, exercises, hints or solutions are supplied."}]},{"type":"paragraph","children":[{"type":"text","value":"For questions the launch slides do not answer, uncertain policies or corrections, email "},{"type":"link","href":"mailto:info@uclai.co.uk","children":[{"type":"text","value":"info@uclai.co.uk"}]},{"type":"text","value":". AI answers may be incorrect; check the cited source pages and current dates."}]}]}],"type":"nexus-session","topics":["nexus-labs","research","research-pillars","research-tracks","conference-planning"],"year":"2026/27","series":"Nexus Labs","archived":true,"origin":"curated","reviewedAt":"2026-10-29T23:48:56.000Z","source":{"url":"https://github.com/UCLAIS/UCLAIS.github.io/blob/24e06da03aa538cbc002767935da6d95d724ede8/knowledge/nexus/2026-27/launch.md","revision":"24e06da03aa538cbc002767935da6d95d724ede8","attribution":"UCL AI Society Nexus Labs; 2026/27 launch presentation","status":"approved"}},"releaseId":"053b96bc7dafd9857faf6870405f36aadd5a89849a66a0166422d24b4cc1d52c"}')}}]);